#include <bits/stdc++.h>
using namespace std;

void solve() {
    long long n;
    cin>>n;
    vector<long long>v(3*n);
    for(long long i=0;i<3*n;i++){
        cin>>v[i];
    }
    sort(v.rbegin(),v.rend());
    vector<long long>prefix(3*n+1,0);
    for(long long i=0;i<3*n;i++){
        prefix[i+1]=prefix[i]+v[i];
    }
    long long ans=0;
    for(long long z=0;z<=2*n;z++){
        long long low=max(0LL,z-n);
        long long high=z/2;
        if(low>high) continue;
        while(low<high){
            long long mid1=low+(high-low)/2;
            long long first=2LL*prefix[mid1]+prefix[2*z-3*mid1];
            long long mid2=mid1+1;
            long long second=2LL*prefix[mid2]+prefix[2*z-3*mid2];
            if(first<=second){
                low=mid1+1;
            }
            else{
                high=mid1;
            }
        }
        long long temp=2LL*prefix[low]+prefix[2*z-3*low];
        long long curr=temp+3LL*prefix[3LL*n-z];
        ans=max(ans,curr);
    }
    cout<<ans<<"\n";
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(NULL);
    int t; cin >> t;
    while(t--) {
        solve();
    }
}
